CREATE TABLE salud_u.adenda_encuentro_clinico (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),id_encuentro uuid NOT NULL REFERENCES salud_u.encuentro_clinico(id) ON DELETE RESTRICT,numero_adenda integer NOT NULL CHECK(numero_adenda>0),motivo text NOT NULL CHECK(length(btrim(motivo)) BETWEEN 1 AND 1000),contenido text NOT NULL CHECK(length(btrim(contenido)) BETWEEN 1 AND 8000),creada_en timestamptz NOT NULL DEFAULT now(),creada_por uuid NOT NULL REFERENCES salud_u.principal(id) ON DELETE RESTRICT,UNIQUE(id_encuentro,numero_adenda));
ALTER TABLE salud_u.adenda_encuentro_clinico ENABLE ROW LEVEL SECURITY; ALTER TABLE salud_u.adenda_encuentro_clinico FORCE ROW LEVEL SECURITY;
CREATE POLICY adenda_encuentro_migrador ON salud_u.adenda_encuentro_clinico FOR ALL TO ${migrator_role} USING(true) WITH CHECK(true);
CREATE FUNCTION salud_u.agregar_adenda_encuentro(p_encuentro uuid,p_motivo text,p_contenido text) RETURNS TABLE(id uuid,numero_adenda integer,creada_en timestamptz,creada_por uuid) LANGUAGE plpgsql SECURITY DEFINER SET search_path=salud_u,pg_temp AS $$
DECLARE e record; numero integer; actor uuid:=salud_u.id_actor_actual();
BEGIN SELECT * INTO e FROM salud_u.encuentro_clinico WHERE id=p_encuentro FOR UPDATE; IF NOT FOUND OR e.estado<>'CLOSED' OR e.id_personal IS DISTINCT FROM salud_u.id_mi_personal_activo() OR NOT(salud_u.tiene_rol_actor('REVIEW_DOCTOR') OR salud_u.tiene_rol_actor('SPECIALIST')) THEN RAISE EXCEPTION 'ADENDA_NO_AUTORIZADA' USING ERRCODE='42501'; END IF; IF length(btrim(coalesce(p_motivo,'')))=0 OR length(btrim(coalesce(p_contenido,'')))=0 THEN RAISE EXCEPTION 'ADENDA_INVALIDA' USING ERRCODE='22023'; END IF; SELECT coalesce(max(a.numero_adenda),0)+1 INTO numero FROM salud_u.adenda_encuentro_clinico a WHERE a.id_encuentro=e.id; INSERT INTO salud_u.adenda_encuentro_clinico(id_encuentro,numero_adenda,motivo,contenido,creada_por) VALUES(e.id,numero,btrim(p_motivo),btrim(p_contenido),actor) RETURNING adenda_encuentro_clinico.id,adenda_encuentro_clinico.numero_adenda,adenda_encuentro_clinico.creada_en,adenda_encuentro_clinico.creada_por INTO id,numero_adenda,creada_en,creada_por; RETURN NEXT; END $$;
CREATE FUNCTION salud_u.listar_adendas_encuentro(p_encuentro uuid) RETURNS TABLE(id uuid,numero_adenda integer,motivo text,contenido text,creada_en timestamptz,creada_por uuid) LANGUAGE plpgsql SECURITY DEFINER SET search_path=salud_u,pg_temp AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM salud_u.encuentro_clinico e WHERE e.id=p_encuentro AND ((salud_u.tiene_rol_actor('REVIEW_DOCTOR') AND e.tipo_encuentro='INITIAL') OR (salud_u.tiene_rol_actor('SPECIALIST') AND e.id_personal=salud_u.id_mi_personal_activo()))) THEN RAISE EXCEPTION 'ADENDA_NO_AUTORIZADA' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT a.id,a.numero_adenda,a.motivo,a.contenido,a.creada_en,a.creada_por FROM salud_u.adenda_encuentro_clinico a WHERE a.id_encuentro=p_encuentro ORDER BY a.numero_adenda; END $$;
GRANT EXECUTE ON FUNCTION salud_u.agregar_adenda_encuentro(uuid,text,text),salud_u.listar_adendas_encuentro(uuid) TO ${runtime_role};
